{"implementation": "def solve(case):
    nodes = case['nodes']
    core = case['core_distance']
    dist_list = case['distances']
    dist_map = {}
    for a, b, d in dist_list:
        key = tuple(sorted((a, b)))
        dist_map[key] = d
    edges = []
    n = len(nodes)
    for i in range(n):
        for j in range(i+1, n):
            a, b = nodes[i], nodes[j]
            key = (a, b)
            d = dist_map[key]
            mrd = max(core[a], core[b], d)
            edges.append((a, b, mrd))
    edges.sort(key=lambda x: (x[2], x[0], x[1]))
    parent = {node: node for node in nodes}
    rank = {node: 0 for node in nodes}
    def find(node):
        while parent[node] != node:
            parent[node] = parent[parent[node]]
            node = parent[node]
        return node
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    mst_edges = []
    total = 0.0
    for a, b, w in edges:
        if union(a, b):
            mst_edges.append([a, b, w])
            total += w
    return {'mst_edges': mst_edges, 'total_weight': total}
